/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «لأنك الله» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["lak2"]={"id":"lak2","title":"لأنك الله","sub":"معارج النفوس المطمئنة، الجزء الثاني","author":"علي جابر الفيفي","coauthors":[],"translator":"","publisher":"دار الحضارة للنشر والتوزيع، الرياض","year":"1444ه","edition":"الطبعة الأولى","series":"لأنك الله (الجزء الثاني)","lead":"الجزء الثاني من تأملات أدبية في أحد عشر اسمًا من أسماء الله الحسنى، تمزج الآية والقصة والمشهد اليومي. يقول مؤلفه إنه ليس كتابًا علميًا «وإنّما هو قلم أديب إن صح لي أن أكون أديبًا، وقلب متأمّل إن صلح لي أن أكون متأمّلًا»","audience":"عام: الشباب والكبار، والمربون والمعلمون في دروس الإيمان؛ يُنتقى منه للصغار","bio":"","chapters":[{"k":"c1","t":"الرحمن","q":"كيف تتجلى رحمة الله فيما نحب وفيما نكره؟","essence":"رحمته تملأ الوجود حتى فيما نكره","kw":["الرحمة","آثار الرحمة","العدل"],"sections":[{"t":"رحمة تملأ الوجود","pg":13,"key":"إنّ رحمته لتظهر في كل نَفَس نتنفّسه، وفي كل صورة نُبصرها، وفي كل همسة نسمعها..","p":["ثم تظهر في أكثر من مئة وستين آية قرآنية.. بل وتختص سورة ذات نسج فريد ونظم متميّز باسم «الرحمٰن»..","إن الرحمٰن إذا نشر رحمته في مكان مظلم أضاء، وفي كهف ضيّق بات فسيحًا، وفي قلب ميّت نبض بالحياة."],"items":[{"h":"فتية الكهف","x":"يتأمل المؤلف قوله تعالى «ينشر لكم ربكم من رحمته» (الكهف 16)، فالكهف الضيق يتسع برحمة الله (ص14)."},{"h":"الاختصاص بالرحمة","x":"«إن الله إذا اختصّك برحمة منه، فقد كفاك كل هموم الحياة وغمومها!» (ص15)."},{"h":"مئة رحمة","x":"يورد حديث مسلم في أن لله مئة رحمة أنزل منها واحدة يتراحم بها الخلق، ويمثّل بالأم التي لا تلقي صغيرها من شاهق ولو أُعطيت أموال الدنيا (ص16 و17)."}]},{"t":"رحمة لا يقيسها مختبر","pg":18,"key":"فلا ماديّة تستطيع أن تحدد مكان هذه الرحمة، ولا مختبر يمكنه أن يقيس حجم هذه الرحمة، ولا ميكروسكوب يقدر على رؤية جزيئات هذا الشعور الفيّاض.","p":["فإن علم ذنبك فهو يحب أن يغفره، وإن سمع تجاوزك فهو يفرح بتوبتك، وإن رأى خطأك فهو يريد أوبتك!"],"items":[{"h":"الاستواء باسم الرحمن","x":"ينبّه إلى أن ذكر الاستواء على العرش جاء مقرونًا باسم الرحمن في موضعين: طه 5 والفرقان 59 (ص18)."},{"h":"فاسأل به خبيرًا","x":"ينقل عن ابن كثير: «أي: استعلم عنه من هو خبير به عالم به فاتبعه واقتد به» (ص19)."}]},{"t":"رحمته فيما نكره","pg":21,"key":"إنّ هذه رحمته سبحانه بعبده الكافر عند عذابه وانتقامه منه، فكيف ستكون رحمته مع المؤمن المنكسر المعترف عند إرادة ثوابه وعطائه؟","p":["فسبحان من رحمته فيما نكره قد تكون أعظم وأظهر من رحمته فيما نحب!"],"items":[{"h":"عذاب من الرحمن","x":"في قوله تعالى «أن يمسك عذاب من الرحمن» (مريم 45) يستنبط «أنّه يمسّ أعداءه بالعذاب مسًّا في بداية أمرهم حتى يثوبوا عن عنادهم ويعودوا» (ص20)."},{"h":"العدل","x":"«فهو سبحانه منزّهٌ عن الظلم، بل هو عدل ويحاسبهم بما يستحقون.» (ص20)."},{"h":"ذكر النار","x":"ذكر الله النار «تحذيرًا لعباده، ورحمة بهم.» (ص15)."},{"h":"دار العجزة","x":"يتأمل حال كبار السن المرضى، ويرى في الموت نفسه وجهًا من تجليات الرحمة (ص21)."}]},{"t":"فانظر إلى آثار رحمة الله","pg":23,"key":"بل إنّ نظرك إلى آثار الرحمة من آثار الرحمة! فلولا رحمته بك لما نظرت، ولما سمعت، ولما عقلت شيئًا!","p":["فافتح نافذة في عقلك، وامتثل من خلالها لأمره لك سبحانه بأن تنظر، فانظر إلى آثار رحمة الله من حولك، أحيِ قلبك بتلك الآثار، وزد حب ربّك في قلبك حبًا وإجلالًا وتعظيمًا."],"items":[{"h":"مشهد الأب","x":"«إن رأيت أبًا يداعب ابنه الصغير، وقد امتلأ قلبه حبًا له، وفرحة به، فانظر إلى آثار رحمة الله» (ص23)."},{"h":"الآية","x":"«فانظر إلى آثار رحمت الله كيف يحيي الأرض بعد موتها» (الروم 50)."}]}],"quiz":[{"q":"بحسب الكتاب، لماذا ذكر الله النار في كتابه؟","o":["تحذيرًا لعباده ورحمة بهم","لإظهار قدرته على الانتقام وحده","لبيان كثرة العصاة في الأرض","لتخويف الكافرين دون المؤمنين"],"why":"تحذيرًا لعباده، ورحمة بهم.","pg":15},{"q":"ماذا يستنبط المؤلف من وصف العذاب في آية مريم 45 بأنه «يمسّ» وأنه «من الرحمن»؟","o":["يبدؤهم بعذاب يسير لعلهم يرجعون","أن العذاب لا يقع على الكافر في الآخرة","أن الرحمن لا يعذب أحدًا من خلقه أبدًا","أن العذاب يقع على المؤمن قبل الكافر"],"why":"أنّه يمسّ أعداءه بالعذاب مسًّا في بداية أمرهم حتى يثوبوا عن عنادهم ويعودوا","pg":20},{"q":"صديق ابتُلي بمرض طويل فظن أن الابتلاء دليل حرمانه من الرحمة؛ أي المعاني يقرره الكتاب؟","o":["قد تكون رحمته فيما نكره أعظم مما نحب","طول المرض علامة غضب لا رحمة فيه أبدًا","الرحمة تختص بالأصحاء والأقوياء دون المرضى","تمنّي الموت مطلوب من المريض عند كل بلاء"],"why":"فسبحان من رحمته فيما نكره قد تكون أعظم وأظهر من رحمته فيما نحب!","pg":22},{"q":"إذا كانت هذه رحمته بالكافر عند عذابه، فما الذي يستنتجه المؤلف؟","o":["رحمته بالمؤمن المنكسر أعظم عند ثوابه","الكافر والمؤمن سواء في الرحمة والجزاء","العذاب في الآخرة يخفّ على كل أحد","المؤمن لا يحتاج إلى رحمة الله ما دام صالحًا"],"why":"إنّ هذه رحمته سبحانه بعبده الكافر عند عذابه وانتقامه منه، فكيف ستكون رحمته مع المؤمن المنكسر المعترف عند إرادة ثوابه وعطائه؟","pg":21},{"q":"لماذا يعدّ المؤلف نظرك إلى آثار الرحمة رحمةً في ذاته؟","o":["لأنه لولا رحمته ما نظرت ولا عقلت","لأن النظر عبادة لا تحتاج إلى نية","لأن آثار الرحمة لا تُرى إلا بالقلب","لأن النظر يزيد الرزق ويوسّع المال"],"why":"بل إنّ نظرك إلى آثار الرحمة من آثار الرحمة! فلولا رحمته بك لما نظرت، ولما سمعت، ولما عقلت شيئًا!","pg":23}],"scene":{"t":"صديق في محنة","x":"صديقك أصيب بمرض طويل، وصار يردد: لو كان الله يرحمني ما ابتلاني. ماذا تقول له؟","opts":["تذكّره بأن رحمة الله قد تكون فيما نكره أعظم مما نحب","توافقه على أن البلاء علامة البعد عن الرحمة","تنصحه بترك التفكير في الأمر والانشغال بالدنيا"],"why":"فسبحان من رحمته فيما نكره قد تكون أعظم وأظهر من رحمته فيما نحب!","pg":22}},{"k":"c2","t":"الجميل","q":"كيف يدل جمال الخلق على جمال الخالق؟","essence":"جميل يحب الجمال ويملأ به الكون","kw":["الجمال","التسبيح","التأمل"],"sections":[{"t":"إن الله جميل يحب الجمال","pg":27,"key":"فهو جميل في ذاته، ويحب الجمال في غيره.. لذلك خلق الخلق على نظام الجمال، وشرَع الشرائع وفق قواعد الجمال!","p":["فهو يخلق الشيء الجميل لأنه جميل، ولا يأتي من الجميل سبحانه إلا الجميل، ويخلقه لأنه يحب الجمال، ويخلقه أيضًا ليسبّحه العبد ويشكره ويعبده وهو يتراءى ذلك الجمال، ويخلقه لتتطبّع نفوس عباده على الجمال!"],"items":[{"h":"الحديث","x":"«إن الله جميل يحب الجمال» رواه مسلم (ص27)."},{"h":"مراتب الجمال","x":"ينقل عن ابن القيم في الفوائد: «وجماله سبحانه على أربع مراتب: جمال الذات وجمال الصفات وجمال الأفعال وجمال الأسماء» (ص27)."}]},{"t":"السلة العجيبة","pg":29,"key":"وأنّ جمال الخلق من الأدلّة على جمال الخالق، فلن يخلق الجمال إلا وهو جميل سبحانه.","p":["ولعل كثرة التسبيح في القرآن الكريم، والأمر به في السنّة النبوية، هو لأن خالق الكون سبحانه قد بنى هذا الكون على دعائم من الإبهار والإدهاش الذي يستنطق التسبيح فطرة، ودون الحاجة إلى تعمّق في التفكير والاستدلال."],"items":[{"h":"حبة برتقال","x":"«هذه حبة برتقال واحدة، احتجت معها إلى أن تستغرق في بحر من التسبيح لهذا الخالق العظيم» (ص30)."},{"h":"سؤال الجمال","x":"يتساءل: لماذا أراد الله أن تكون الفاكهة جميلة؟ ويقول إنه لا يجد جوابًا يعبّر عنه «وإنما أستطيع أن أشعر به..» (ص31)."}]},{"t":"الصباح مسرح الجمال","pg":34,"key":"لتدرك أنّ الله جميل يحبّ الجمال! لا يحبّه منك فقط، بل يحبّ أن يوجده في الكون، فيغدو الكون مترعًا به، مكتظًّا بتفاصيله المبهرة!","p":["مشكلتنا أننا نظن الجمال في الإنسان مقتصرًا على شكل عينيه، وملامح وجهه، وجمال ابتسامته، وننسى الجمال في قامته"],"items":[{"h":"نغمة الصباح","x":"«الصباح مسرح من مسارح الجمال» (ص34)."},{"h":"صوت الحمام","x":"يراه «دليل على أن خالق الجمال يجعل الأشياء الغامضة جزءًا من لوحة جميلة» (ص34)."},{"h":"أحسن تقويم","x":"يورد قصة رجل حلف أن زوجته أجمل من القمر، فأُفتي بأنها لا تطلق لقوله تعالى «لقد خلقنا الإنسان في أحسن تقويم» (التين 4) (ص33)."}]},{"t":"الفراشة والحاجة إلى الغباء","pg":35,"key":"وبصدق فإنّ الرافض لوجود الله يحتاج أن يسلّم عقله إلى أمور مغيّبة لا يدرك كنهها أكثر بكثير من المؤمن بوجود الله!","p":["يحتاج الملحد أن يكون ميتافيزيقيًّا بقدر كبير جدًا حتى يؤمن بتلك الحزمة الكبيرة من التناقضات، والخيالات، والغباءات!"],"items":[{"h":"الفراشة","x":"يتأمل ألوان جناح الفراشة، ويرد على من ينسبها إلى طبيعة عمياء: «مضحكون هم! يستطيعون أن يأتوا بالغرائب ليهربوا من الله! ولكنّ نَفَسهم في هذا الهرب قصير جدًا!» (ص31)."}]}],"quiz":[{"q":"ما الذي يجعله المؤلف دليلًا على جمال الخالق سبحانه؟","o":["جمال المخلوقات التي نراها حولنا","كثرة الكتب المؤلفة في علم الجمال","إجماع الشعراء على وصف الطبيعة","قدرة الإنسان على صنع الأشياء الجميلة"],"why":"وأنّ جمال الخلق من الأدلّة على جمال الخالق، فلن يخلق الجمال إلا وهو جميل سبحانه.","pg":29},{"q":"ذكر ابن القيم أن جمال الله على أربع مراتب؛ أي مما يلي ليس منها؟","o":["جمال الكون","جمال الصفات","جمال الأفعال","جمال الأسماء"],"why":"وجماله سبحانه على أربع مراتب: جمال الذات وجمال الصفات وجمال الأفعال وجمال الأسماء","pg":27},{"q":"لماذا كثر التسبيح في القرآن والسنة كما يرى المؤلف؟","o":["لأن الكون بُني على إبهار يستنطقه فطرة","لأنه لا يُدرك إلا بعد استدلال عميق طويل","لأنه يغني المسلم عن التأمل في الكون","لأنه خاص بمن شاهد المعجزات بعينه"],"why":"ولعل كثرة التسبيح في القرآن الكريم، والأمر به في السنّة النبوية، هو لأن خالق الكون سبحانه قد بنى هذا الكون على دعائم من الإبهار والإدهاش الذي يستنطق التسبيح فطرة، ودون الحاجة إلى تعمّق في التفكير والاستدلال.","pg":29},{"q":"ما الفكرة التي يستخرجها المؤلف من قصة من حلف أن زوجته أجمل من القمر؟","o":["أن الجمال يشمل القامة والخلقة كلها","أن جمال الوجه هو أساس جمال الإنسان","أن القمر أجمل ما خلق الله في الكون","أن جمال الإنسان في ثيابه وزينته"],"why":"مشكلتنا أننا نظن الجمال في الإنسان مقتصرًا على شكل عينيه، وملامح وجهه، وجمال ابتسامته، وننسى الجمال في قامته","pg":33},{"q":"بحسب الكتاب، الرافض لوجود الله يحتاج إلى:","o":["تسليم عقله لمغيّبات أكثر من المؤمن","أدلة حسية أقل مما يحتاجه المؤمن","ترك العلم التجريبي كله ليبقى على رأيه","قراءة الفلسفة ليفهم جمال الكون"],"why":"وبصدق فإنّ الرافض لوجود الله يحتاج أن يسلّم عقله إلى أمور مغيّبة لا يدرك كنهها أكثر بكثير من المؤمن بوجود الله!","pg":35}],"scene":{"t":"سلة فاكهة","x":"عدت إلى البيت بسلة فاكهة، وأبناؤك منشغلون بأجهزتهم. ماذا تفعل؟","opts":["تضعها أمامهم وتتأمل معهم ألوانها وصنعتها ثم تسبّحون الخالق","تطلب منهم أن يأكلوا بسرعة ليعودوا إلى دروسهم","تحدثهم عن فوائدها الغذائية دون ذكر خالقها"],"why":"وأنّ جمال الخلق من الأدلّة على جمال الخالق، فلن يخلق الجمال إلا وهو جميل سبحانه.","pg":29}},{"k":"c3","t":"الوهاب","q":"كيف نسأل الوهاب، وماذا يهب؟","essence":"يهب بلا سؤال، فكيف إذا سُئل؟","kw":["الهبة","الدعاء","الذرية"],"sections":[{"t":"معنى الوهاب","pg":39,"key":"وصيغة فعّال تعني المبالغة، فليس سبحانه واهبًا بل وهّابًا: كثيرًا ما يهب ويعطي ويجود، لذلك سمّى نفسه بالوهّاب..","p":["فيعطي من يسأله ومن لا يسأله! ويعطي من يحتاج ومن لا يحتاج! ويعطي من يعبده ومن لا يعبده!"],"items":[{"h":"يأمرك بالطلب","x":"«فالكرماء يعطونك مرة، فإن طلبت منهم مرّة ثانية، قد يتأففون لطلبك! أما الله سبحانه فهو يهب عطاءات لا حدّ لها، ثم يرضى عنك إذا طلبت منه، بل إنّه يأمرك أمرًا أن تطلب منه» (غافر 60) (ص39)."},{"h":"يهب عظيمًا","x":"«فكرماء بني آدم يهبون، في العادة، المال، أما الله فإن المال أقل ما يهبك إيّاه!» (ص40)."},{"h":"يهب أعداءه","x":"أعطى إبليس الإنظار إلى يوم الوقت المعلوم (الحجر 36 إلى 38) (ص41)."}]},{"t":"يهب قبل أن يُستوهب","pg":42,"key":"أتعلم لماذا؟ لأنّه الوهاب؛ يهب دون أن يُطلب، وقبل أن يُستوهب.. والسؤال: ما دامت هذه عطاءاته قبل السؤال، فكيف ستكون عطاءاته بعد السؤال؟","p":["إنّك لن تتنازل عن بصرك بأموال قارون كلّها!! هذه إحدى النعم التي نادرًا ما تشعر بها.."],"items":[{"h":"ضع نقطة","x":"قصة شاب تاب في عمرة فتتابعت عليه النعم: «يوم واحد هو الفارق بين توبته، وبداية حياته الرغيدة!» (ص43)."},{"h":"قل يا الله","x":"«إن الوهّاب لم يخلق بابًا دون هباته وعطاياه، فقط قل: يا الله، ثم استبشر خيرًا..» (ص43)."}]},{"t":"التوسل بالهبات ودعاء بلا سقف","pg":40,"key":"بل إنك إن أردت أن تستوهبه شيئًا فإنّ من طُرق هذا الاستيهاب والاستجداء أن تذكر في دعائك بعض ما سبق ووهبك إيّاه، فتكون هبته السالفة أمرًا تستجدي به هبة جديدة!","p":["اطلب واجعل سقف دعواتك أعلى ما يمكن.."],"items":[{"h":"زكريا","x":"«ولم أكن بدعائك رب شقيا» (مريم 4)، وينقل عن ابن عاشور أنه قد عهد من الله الاستجابة كلما دعاه (ص40)."},{"h":"غرابة الدعاء","x":"«لم يكن الأنبياء في كثير من دعواتهم يدعون بالقريب وإنما بالغريب!» (ص45)، ومنه دعاء سليمان بملك لا ينبغي لأحد من بعده، ودعاء نوح (القمر 11 و12) (ص44 و46)."},{"h":"بعد الإخفاق","x":"«استغل أوبتك من إخفاقاتك بطلب أبعد خيالاتك!» (ص43)."}]},{"t":"الوهاب والذرية","pg":48,"key":"لما نظرت في القرآن وجدت ارتباطًا وثيقًا بين اسم الوهّاب، وفعل الوهب، وبين الذريّة والولد..","p":["وكذلك رب العالمين إن كنت تطلب منه الذريّة فلا أنسب من استخدامك لاسم الوهاب، وصفة الوهب، مع حضور القلب، والإلحاح والثقة، وربنا كريم وهاب، لا يعجزه شيء، ولا يعظم عليه شيء."],"items":[{"h":"الشواهد","x":"آل عمران 38، وإبراهيم 39، ومريم 5، والصافات 100، والأنبياء 72 و90، وص 30، والشورى 49 (ص48)."},{"h":"هبة امرأة عمران","x":"نذرت ما في بطنها فوهبها الله مريم، ثم جعلها أمًّا لعيسى عليه السلام (ص49)."},{"h":"القليل بالكثير","x":"«ومن مظاهر كرمه أنّه يجازي القليل بالكثير، ويثيب على العمل اليسير إذا كان خالصًا صوابًا بالعطاء الجزيل!» (ص50)."}]}],"quiz":[{"q":"ما دلالة مجيء الاسم على صيغة «فعّال» كما يقرره المؤلف؟","o":["كثرة الهبة والعطاء والجود","أن هبته للمؤمنين خاصة","أن عطاءه بعد السؤال فقط","أن هبته في الآخرة دون الدنيا"],"why":"وصيغة فعّال تعني المبالغة، فليس سبحانه واهبًا بل وهّابًا: كثيرًا ما يهب ويعطي ويجود، لذلك سمّى نفسه بالوهّاب..","pg":39},{"q":"رجل تأخر عنه الولد؛ ما الأنسب في دعائه بحسب المؤلف؟","o":["أن يدعو باسم الوهاب بحضور قلب وإلحاح","أن يكتفي بالعلاج ويترك الدعاء جانبًا","أن يدعو مرة واحدة ثم يترك الأمر كليًا","أن يدعو باسم القوي لأنه أنسب لكل حاجة"],"why":"وكذلك رب العالمين إن كنت تطلب منه الذريّة فلا أنسب من استخدامك لاسم الوهاب، وصفة الوهب، مع حضور القلب، والإلحاح والثقة، وربنا كريم وهاب، لا يعجزه شيء، ولا يعظم عليه شيء.","pg":49},{"q":"على أي شيء استدل المؤلف بقول زكريا «ولم أكن بدعائك رب شقيا»؟","o":["التوسل بما سبق من عطاء الله وإجابته","أن الدعاء لا يُستجاب إلا في الكبر","أن الإلحاح في الدعاء أمر مكروه","أن الأنبياء لا يسألون الله الولد صراحة"],"why":"بل إنك إن أردت أن تستوهبه شيئًا فإنّ من طُرق هذا الاستيهاب والاستجداء أن تذكر في دعائك بعض ما سبق ووهبك إيّاه، فتكون هبته السالفة أمرًا تستجدي به هبة جديدة!","pg":40},{"q":"ماذا يقصد المؤلف بما سماه «غرابة الدعاء»؟","o":["أن يُسأل الله البعيد لا القريب فقط","أن يدعو العبد بألفاظ لم ترد قط","أن يكون الدعاء في أوقات نادرة فقط","أن يُخفي العبد دعاءه عن الناس دائمًا"],"why":"لم يكن الأنبياء في كثير من دعواتهم يدعون بالقريب وإنما بالغريب!","pg":45},{"q":"ما الفرق بين عطاء الكرماء من البشر وعطاء الله في الكتاب؟","o":["الله يرضى بالطلب ويأمر به والبشر قد يتأففون","البشر يعطون بلا سؤال والله لا يعطي إلا بسؤال","عطاء الله للأغنياء وعطاء البشر للفقراء","البشر يعطون الكثير والله يعطي القليل"],"why":"فالكرماء يعطونك مرة، فإن طلبت منهم مرّة ثانية، قد يتأففون لطلبك! أما الله سبحانه فهو يهب عطاءات لا حدّ لها، ثم يرضى عنك إذا طلبت منه، بل إنّه يأمرك أمرًا أن تطلب منه","pg":39}],"scene":{"t":"حياء بعد التوبة","x":"شاب تاب حديثًا، ويستحيي أن يسأل الله وظيفة وزواجًا لكثرة ذنوبه السابقة. بماذا تنصحه؟","opts":["أن يسأل الوهاب بيقين ويرفع سقف دعائه بعد توبته","أن ينتظر سنوات حتى يستحق أن يسأل الله شيئًا","أن يكتفي بالاستغفار ولا يسأل شيئًا من الدنيا"],"why":"استغل أوبتك من إخفاقاتك بطلب أبعد خيالاتك!","pg":43}},{"k":"c4","t":"الحق","q":"لماذا لا يحتاج الإيمان بالله إلى برهان بعيد؟","essence":"آياته في كل شيء، والكبر يحجبها","kw":["الحق المبين","الآيات","الإلحاد"],"sections":[{"t":"الحق المبين","pg":53,"key":"من أسمائه سبحانه الحقّ المبين، فهو الحق الذي ليس بعده إلا الباطل، ظاهر ظهورًا جليًّا، لا يماري في وجوده، وفي عليائه، وفي جلاله إلا أعمى البصيرة.","p":["وفي كل شيء له آية، وفي كل خلق له برهان، لا تفنى آياته، ولا تنقضي براهينه."],"items":[{"h":"يريدون آية","x":"يونس 20 و101: «هم يريدون آية ليؤمنوا، آية واحدة تكفيهم حتى يعلنوا إيمانهم!» (ص54)."},{"h":"حشد من الآيات","x":"«هناك حشد هائل من الآيات تمور حولنا، لا تحتاج منا إلا إلى النظر العابر، حتى نتفاجأ بها!» (ص54)."},{"h":"ابن عاشور","x":"«وقد عمم ما في السماوات والأرض لتتوجه كل نفس إلى ما هو أقرب إليها، وأيسر استدلال عليه لديها» (ص54)."}]},{"t":"يقين يغلفه الجحود","pg":55,"key":"هناك يقين في أعماقهم يغلّفونه بالكفر والصدود عنه سبحانه!","p":["فقط انظروا حولكم، فكل شيء ترونه هو آية عليه، ودلالة واضحة تشير إليه"],"items":[{"h":"الآية","x":"«وجحدوا بها واستيقنتها أنفسهم» (النمل 14)."},{"h":"كثرة الأدلة","x":"«إنّهم يضيقون ذرعًا بكثرة الأدلّة الدالّة عليه» (ص56)."},{"h":"لقد علمت","x":"قول موسى لفرعون (الإسراء 102): «لقد علمت ذلك جيّدًا، إن نفسك تفضحك»، ثم يقرر: «الكبر يدفن بذور الإيمان» (غافر 56) (ص58)."}]},{"t":"وفي الليل","pg":57,"key":"إنّ أعتى الملاحدة يتحوّل في الليل إلى نصف مؤمن!","p":["إن الرعب الذي يتسلل إلى قلبك وأنت تسمع صوت الرعود أثناء استلقائك على سريرك ليلًا دليل على أنّ الذي خلق هذا الرعب في قلبك أراد أن يذلّ كبرياءك بشيء من الخوف، حتى تؤمن به!"],"items":[{"h":"الافتتاحية","x":"«الليل مرهق جدًا بالنسبة لأولئك الذين يعاندون الله، ويكفرون به!» (ص51)."},{"h":"طبيعة طبيعة","x":"ينقل حكاية عن حافظ إبراهيم مع رجل ينكر الخالق، فلما أفزعه أمر هتف باسم الله: «بماذا ستهتف؟ طبيعة طبيعة؟» (ص59)."}]},{"t":"دخل ملحدًا وخرج مؤمنًا","pg":59,"key":"خرج مؤمنًا لأن الله هو الحق المبين!","p":[],"items":[{"h":"إعصار الجسر","x":"رجل أدركه إعصار على جسر في إسطنبول فقال: «دخلت الجسر ملحدًا، وخرجت منه مؤمنًا!» (ص59)."},{"h":"لورانس براون","x":"طبيب ملحد مرضت ابنته فدعا: «إن كنت موجودًا أيها الإله فاشف ابنتي!» فشُفيت: «دخل إلى المستشفى بإلحاده، وخرج منها بإيمانه!» (ص61)."}]}],"quiz":[{"q":"لماذا يرى المؤلف طلب المشركين «آية» واحدة في غير محله؟","o":["لأن الآيات حولهم كثيرة يكفيها نظر عابر","لأن الآيات لا تُرى إلا في زمن الأنبياء","لأن الإيمان لا صلة له بالنظر والتفكر","لأن الله لا يُظهر آياته إلا للعلماء وحدهم"],"why":"هناك حشد هائل من الآيات تمور حولنا، لا تحتاج منا إلا إلى النظر العابر، حتى نتفاجأ بها!","pg":54},{"q":"ماذا يستفاد من قوله تعالى «وجحدوا بها واستيقنتها أنفسهم» كما يشرحه المؤلف؟","o":["أن في أعماقهم يقينًا يغلّفونه بالصدود","أن الكافر لا يعرف الحق في داخله مطلقًا","أن الجحود سببه قلة الأدلة على الخالق","أن اليقين ينجي صاحبه ولو أعرض وجحد"],"why":"هناك يقين في أعماقهم يغلّفونه بالكفر والصدود عنه سبحانه!","pg":55},{"q":"ما الذي «يدفن بذور الإيمان» بحسب الكتاب؟","o":["كبر النفس","كثرة الأسئلة","قلة الاطلاع","طول التفكير"],"why":"الكبر يدفن بذور الإيمان","pg":58},{"q":"شاب يزعم أنه لا يؤمن إلا بما يرى، لكنه يفزع من الرعد ليلًا؛ كيف يفسر المؤلف فزعه؟","o":["أراد خالقه أن يذل كبرياءه ليؤمن","خوف طبيعي لا دلالة له على شيء","دليل على ضعف عقله وقلة علمه بالطبيعة","عقوبة عاجلة من الله على إلحاده لا غير"],"why":"إن الرعب الذي يتسلل إلى قلبك وأنت تسمع صوت الرعود أثناء استلقائك على سريرك ليلًا دليل على أنّ الذي خلق هذا الرعب في قلبك أراد أن يذلّ كبرياءك بشيء من الخوف، حتى تؤمن به!","pg":57},{"q":"ما الذي يجمع قصة إعصار الجسر وقصة الطبيب لورانس براون؟","o":["شدة كشفت لكل منهما الحق فخرج مؤمنًا","أن كليهما كان عالمًا في الفيزياء","أن كليهما آمن بعد مناظرة طويلة","أن كليهما نجا دون أن يلجأ إلى الله أبدًا"],"why":"خرج مؤمنًا لأن الله هو الحق المبين!","pg":59}],"scene":{"t":"دليل واحد","x":"زميل لك يحب الجدال في وجود الله، ويطلب منك «دليلًا واحدًا» فقط. ماذا تفعل؟","opts":["تلفت نظره بهدوء إلى الآيات القريبة في نفسه وما حوله","تقطع علاقتك به فورًا دون أي حوار","تعطيه كتبًا فلسفية معقدة وتتركه"],"why":"فقط انظروا حولكم، فكل شيء ترونه هو آية عليه، ودلالة واضحة تشير إليه","pg":55}},{"k":"c5","t":"الحكيم","q":"كيف تظهر حكمة الله في خلقه وفي أمره؟","essence":"يضع كل شيء في موضعه خلقًا وأمرًا","kw":["الحكمة","الخلق والأمر","التسليم"],"sections":[{"t":"معنى الحكيم","pg":65,"key":"الحكمة هي وضع الأمر في موضعه، والحكيم هو الذي يفعل ذلك!","p":["تظهر أسرارها في كثير من شؤون خلقه وأمره، ويغمُض منها الكثير أيضًا، ويختص سبحانه عباده المتفكرين بغوامض حكمته فيزيد يقينهم به، وحبّهم وإجلالهم له.","فالحكمة البالغة تتجلّى وتتمظهر في هذين الركنين العظيمين: الخلق، والأمر.."],"items":[{"h":"الآية","x":"«ألا له الخلق والأمر» (الأعراف 54) (ص66)."}]},{"t":"وفي أنفسكم","pg":66,"key":"لو انعكس الجلد فكان الأعلى أسفل لصعب علينا الإمساك بالأشياء","p":["إن الذي خلقك حكيم، ولن تجد مفصلًا أو عضوًا أو تكوينًا في جسدك ليس له فائدة، وإن جهلت شيئًا، فإن العلم في الغد سيخبرك بحكمته"],"items":[{"h":"الأذن البارزة","x":"«أنّ الله أراد بهذا التكوين الحكيم أن يمنع دخول الماء إلى طبلة أذنك» (ص67)."},{"h":"الأنف والحاجبان","x":"الأنف قاس أعلاه لين أسفله، والحاجبان من «ثلاثة حرّاس» للعين (ص67 و68)."},{"h":"السمع","x":"«فللسمع كما هو معروف عتبتان دنيا وعليا، فالعتبة الدنيا تضمن لك عدم سماع الأصوات المنخفضة جدًا، والعليا تضمن لك عدم سماع الأصوات المرتفعة جدًا.» (ص75)."}]},{"t":"حكمة الأمر والتشريع","pg":68,"key":"فلم يأمر سبحانه إلا بما يطابق مقتضى العبودية، ويتضمّن مصالح العباد، ويستلزم سعادة الدنيا والآخرة..","p":["فإن الذكر وإن أخذ الضعف هنا، فإنّه يؤمر بالنفقة هناك! أما الأنثى فتأخذ النصف ثم لا تؤمر بنفقة! فمالها لها، وماله له ولغيره! فهنا وجه من أوجه الحكمة البالغة!"],"items":[{"h":"الصلوات الخمس","x":"لم تكن أكثر فيشق أداؤها، ولا أقل فيبهت معنى العبودية (ص68 و69)."},{"h":"الصوم","x":"«فهذا جوع يذكرك بالفقير ومسكنته، وخواء يصرفك عن الدنيا وبهرجها، وامتثال دقيق يوقظ في نفسك معنى العبوديّة!» (ص69)."},{"h":"الغموض اختبار","x":"يجعل في بعض التشريع غموضًا «فيظهر المؤمن من المنافق، والمسلم من المتشكك، والخاضع من النافر!» (ص70)."},{"h":"حكمة الباري","x":"في الرد على من اعترض على حد السرقة: «عندما كانت أمينة، كانت ثمينة! فلمّا خانت، هانت!» (ص71)."}]},{"t":"تأخر الإجابة","pg":72,"key":"ومما يتجلّى فيه اسم الحكيم، تباعد ما بين دعاء العبد وإجابة الرب، فهو القدير على أن يُسرع بالإجابة ويتحقق المطلوب، فلا تُنزل يديك إلا والإجابة ماثلة أمامك، ولكنّ حكمته اقتضت ألّا يحدث ذلك في كثير من الدعوات!","p":["ستعلم أنّ وجود حالة تقتضي دعاء والتجاء أمر محبوب إلى الله؛ لأن عبده في تلك الحالة يكون قد تلبّس بأسمال العبوديّة، فاستحقّ بها هبات الربوبيّة.."],"items":[{"h":"الغنى المؤجل","x":"قد يكون أصلح ما يصلح الفقير «أن يتأجل ذلك الغنى شيئًا من الوقت» (ص73)."},{"h":"حسن الظن","x":"«فلا تظنّ بالحكيم تخلّف حكمته، ولا بالرحيم قصور رحمته.» (ص74)."}]},{"t":"عقول تتساءل","pg":80,"key":"وبعد، هل آن لنا أن نُسجد أرواحنا للحكيم الخبير، وأنْ نعلم أنّ حكمته أعظم من تساؤلاتنا، وأنّه لا يقدّر إلا الأصلح، ولا يُشرّع إلا الأحسن، ولا يقضي إلا بما هو خير؟","p":["عقولنا هذه التي يعتريها ما يعتريها مما ذكرناه وما لم نذكره لا تصلح أن تتساءل عن الحكمة في تشريع ما، أو في خلق ما.."],"items":[{"h":"مسكين هذا الإنسان","x":"يذكر الزهايمر والوسواس والرهاب والشك أمثلة على هشاشة العقل البشري (ص77 إلى 79)."}]}],"quiz":[{"q":"ما تعريف الحكمة الذي يذكره المؤلف؟","o":["وضع الأمر في موضعه","الإكثار من العلم","سرعة الفعل مع إتقانه","الإمهال وترك المعاجلة"],"why":"الحكمة هي وضع الأمر في موضعه، والحكيم هو الذي يفعل ذلك!","pg":65},{"q":"في أي ركنين تتجلى الحكمة البالغة بحسب المؤلف؟","o":["الخلق والأمر","الدنيا والآخرة","الغيب والشهادة","الرزق والأجل"],"why":"فالحكمة البالغة تتجلّى وتتمظهر في هذين الركنين العظيمين: الخلق، والأمر..","pg":66},{"q":"بم يجيب الكتاب من رأى نصيب الأنثى في الميراث ظلمًا؟","o":["الذكر يأخذ الضعف ويُلزم بالنفقة دونها","الذكر أكثر عبادة فاستحق نصيبًا أكبر منها","الأنثى لا تملك مالها بعد زواجها","الأنثى أقل حاجة إلى المال من الذكر"],"why":"فإن الذكر وإن أخذ الضعف هنا، فإنّه يؤمر بالنفقة هناك! أما الأنثى فتأخذ النصف ثم لا تؤمر بنفقة! فمالها لها، وماله له ولغيره! فهنا وجه من أوجه الحكمة البالغة!","pg":70},{"q":"دعوت الله طويلًا ولم تر الإجابة بعد؛ ماذا يقرر المؤلف في هذا؟","o":["الالتجاء محبوب إلى الله والتأخير لحكمة","تأخر الإجابة يعني أن الدعاء مردود حتمًا","الأولى ترك الدعاء والاكتفاء بالسعي","الإجابة لا تأتي إلا بعد بلوغ الكبر"],"why":"ستعلم أنّ وجود حالة تقتضي دعاء والتجاء أمر محبوب إلى الله؛ لأن عبده في تلك الحالة يكون قد تلبّس بأسمال العبوديّة، فاستحقّ بها هبات الربوبيّة..","pg":73},{"q":"لماذا لا تصلح عقولنا حكمًا على حكمة الله في رأي المؤلف؟","o":["لأنها يعتريها النسيان والوسواس والشك","لأن العقل مذموم في الشرع مطلقًا","لأن الحكمة لا تظهر لأحد من الخلق","لأن التفكر في الخلق والتشريع منهي عنه"],"why":"عقولنا هذه التي يعتريها ما يعتريها مما ذكرناه وما لم نذكره لا تصلح أن تتساءل عن الحكمة في تشريع ما، أو في خلق ما..","pg":80}],"scene":{"t":"سؤال في الفصل","x":"سألك طالب: كيف تُقطع اليد في سرقة ربع دينار، وديتها خمسمئة دينار؟","opts":["تشرح له أنها لما كانت أمينة كانت ثمينة، فلما خانت هانت","تنهره عن السؤال وتأمره بالسكوت","تقول له إن الحكم قديم لا يناسب زماننا"],"why":"عندما كانت أمينة، كانت ثمينة! فلمّا خانت، هانت!","pg":71}},{"k":"c6","t":"العليم","q":"كيف يغيّر علم الله المحيط حياة العبد؟","essence":"علمه محيط؛ مطمئن ومخيف ومحفّز","kw":["العلم","الإخلاص","الحلم"],"sections":[{"t":"كل شيء","pg":83,"key":"ومُطَمْئِنٌ جدًا الحديث عن علم الله تعالى، ومخيف في ذات الوقت، ومحفّز للعمل أيضًا!","p":["نؤمن أن الله يعلم كلّ شيء، ثم لا نتأمّل في كلمة «كل شيء» التي لو أعطيناها دقائق تأمّلية لأُصبنا بالذهول!"],"items":[{"h":"مثال عمر","x":"يعلم سبحانه كل تفاصيل حياة عمر بن الخطاب، «ويعلم مثل الذي يعلمه عن عمر عن كل إنسان في الوجود، بل عن كل شيء في الوجود!» (ص84)."},{"h":"قد سمع","x":"قصة خولة بنت ثعلبة (المجادلة 1)، وقول عائشة: «الحمد لله الذي وسع سمعه الأصوات!» (ص85)."},{"h":"يعلمها","x":"«ولكن انتظر، هل قال تعالى: يعلم عددها؟ أم قال: «يعلمها»؟ ليس فقط العدد! إنّه يعلم كل ما يتّصل بها من معلومات!» (الأنعام 59) (ص86)."}]},{"t":"أن تعلم أن الله يعلم","pg":88,"key":"فالخطوة الأولى لإحسانك في عبادتك وإخلاصك في دعائك هي أن تعلم أنّ الله يعلم!","p":["لأنّه العليم، الذي لا ينتج علمه عن تعلّم وإنّما هو عليم بذاته، لا يمكن لمعلومة أن توجد دون أن يكون لديه علمها قبل وأثناء وبعد وجودها!"],"items":[{"h":"أثر عن عمر","x":"«من خلصت نيته كفاه الله تعالى ما بينه وبين الناس» (حلية الأولياء) (ص87)."},{"h":"الفضيل بن عياض","x":"«والله لئن علم الله منك إخراج الآدميين من قلبك حتى لا يكون في قلبك مكان لغيره؛ لم تسأله شيئًا إلا أعطاك» (ص87 و88)."}]},{"t":"طمأنينة العلم وحلم العليم","pg":90,"key":"عندما يعلم ربّك ووليّك وحاميك والمدافع عنك كل شيء في وجودك! فممن تخاف؟ وعلى ماذا تحزن؟ ولماذا تهتم؟","p":["إنّك لن تحتاج في دعائك له أن تسرد كل التفاصيل، يكفيك أن تقول: يا ربّ ارفع عنّي ما أصابني! لأنّه لا أحد أعلم منه بما أصابك","ما أجمل الحلم بعد العلم، لأن علم الإنسان ببواطن الناس يستغضبه ويُحنقه، أما علم الله سبحانه فلا يَنقُص من حلمه ورحمته شيئًا."],"items":[{"h":"يحذّر ثم يطمئن","x":"البقرة 235: «بل إنّه يحذرنا من علمه، ثم يطمئننا بحلمه» (ص92)."},{"h":"العلم والقدرة","x":"فاطر 44: «فعلمه بكل شيء يوازي قدرته على كل شيء.» (ص91)."}]},{"t":"قاع البحر: جهل الإنسان","pg":93,"key":"ولكن الإنسان الضعيف لا يعلم الغيب، لهذا فهو لا يستكثر من الخير! ويمسه السوء ليل نهار..","p":["يعلم ما كان، وما يكون، وما لم يكن لو كان كيف يكون!"],"items":[{"h":"فرعون وقارون","x":"لو علم قارون بخسف داره لانتقل، لكن «المشكلة ليست في الدار، وإنما في صاحب الدار!» (ص94)."},{"h":"السر وأخفى","x":"«السر نعلمه، ولكن ما هو الأخفى من السر؟ إنه كما يقول المفسرون: الوساوس!» (طه 7) (ص97)."}]}],"quiz":[{"q":"يصف المؤلف الحديث عن علم الله بثلاثة أوصاف معًا؛ ما هي؟","o":["مطمئن ومخيف ومحفّز للعمل","مخيف ومحزن ومثقل للنفس","مطمئن ومريح وداع إلى الراحة","غامض وصعب وخاص بالعلماء"],"why":"ومُطَمْئِنٌ جدًا الحديث عن علم الله تعالى، ومخيف في ذات الوقت، ومحفّز للعمل أيضًا!","pg":83},{"q":"لماذا نبّه المؤلف على لفظ «يعلمها» في آية الأنعام 59؟","o":["لأنه يعلم كل ما يتصل بها لا عددها فقط","لأن عدد أوراق الشجر لا يمكن إحصاؤه","لأن الآية خاصة بأوراق شجر الجنة","لأن العلم بالعدد أعظم من العلم بالتفاصيل"],"why":"ولكن انتظر، هل قال تعالى: يعلم عددها؟ أم قال: «يعلمها»؟ ليس فقط العدد! إنّه يعلم كل ما يتّصل بها من معلومات!","pg":86},{"q":"ما الخطوة الأولى لإحسان العبادة وإخلاص الدعاء عند المؤلف؟","o":["أن تعلم أن الله يعلم","أن تكثر من النوافل","أن تحفظ الأذكار المأثورة","أن تختار أفضل الأوقات"],"why":"فالخطوة الأولى لإحسانك في عبادتك وإخلاصك في دعائك هي أن تعلم أنّ الله يعلم!","pg":88},{"q":"ما الفرق بين علم الإنسان ببواطن الناس وعلم الله بعباده كما في الكتاب؟","o":["علم الإنسان يستغضبه، وعلمه لا ينقص حلمه","كلاهما يقود إلى المعاجلة بالعقوبة","علم الله مجمل وعلم الإنسان مفصّل دقيق","علم الإنسان أوسع من غيره في شؤون الدنيا خاصة"],"why":"ما أجمل الحلم بعد العلم، لأن علم الإنسان ببواطن الناس يستغضبه ويُحنقه، أما علم الله سبحانه فلا يَنقُص من حلمه ورحمته شيئًا.","pg":93},{"q":"أصابك همّ متشعب لا تحسن شرحه؛ ماذا يقول المؤلف عن دعائك؟","o":["يكفيك أن تقول: يا رب ارفع عني ما أصابني","يلزمك أن تسرد كل التفاصيل حتى يُستجاب لك","لا تدعُ حتى تجد من يكتب لك دعاءً","أجّل الدعاء حتى تهدأ نفسك ويزول الهم"],"why":"إنّك لن تحتاج في دعائك له أن تسرد كل التفاصيل، يكفيك أن تقول: يا ربّ ارفع عنّي ما أصابني! لأنّه لا أحد أعلم منه بما أصابك","pg":90}],"scene":{"t":"عمل في الخفاء","x":"تقوم بعمل صالح في الخفاء منذ مدة، ولم يشكرك أحد، فبدأت همتك تفتر. ماذا تفعل؟","opts":["تتذكر أن الله يعلم ما في قلبك فيكفيك علمه","تعلن عملك للناس حتى ينال حقه من التقدير","تترك العمل ما دام لا أحد يلاحظه"],"why":"فالخطوة الأولى لإحسانك في عبادتك وإخلاصك في دعائك هي أن تعلم أنّ الله يعلم!","pg":88}},{"k":"c7","t":"الفتاح","q":"كيف يفتح الله على عباده أبواب الرحمة والعلم والدعاء؟","essence":"بيده مفاتيح الفرج والعلم والقبول","kw":["الفتوح","الشكر","البشرى"],"sections":[{"t":"الدنيا حقل أقفال","pg":101,"key":"ولكنّ الفتّاح العليم سبحانه يفتح مغاليق الأمور، ويذلل صعاب الحياة، ويجعل المستحيل ممكنًا، فبيده سبحانه مفاتيح الفرج.","p":["إذن فالرحمات تُفتح، لتتدفق علينا، وتملأنا بالحياة!"],"items":[{"h":"الآية","x":"«ما يفتح الله للناس من رحمة فلا ممسك لها» (فاطر 2) (ص101)."},{"h":"الشكر","x":"«إن الشكر لا يضمن بقاء الرحمة فحسب، بل ويتكفّل بزيادتها!» (إبراهيم 7) (ص102)."},{"h":"قانون البشرى","x":"«فهو سبحانه لا يرسل الرحمة وحدها، بل يرسل قبلها البشائر التي تهيئك لتقبّل تلك الرحمات، وتلقّي تلك البركات.» (الفرقان 48) (ص102)."}]},{"t":"فتوحات العلم","pg":103,"key":"فيفتح سبحانه من العلم، وفي العلم، وللعلم!","p":["وهذا لا يأتي إلا بفتح ربّاني، وتوفيق من الله عظيم."],"items":[{"h":"من العلم","x":"كان ابن تيمية إذا استغلقت عليه آية مرّغ وجهه في التراب وقال: يا معلّم داود علمني، ويا مفهّم سليمان فهمني (ص103)."},{"h":"في العلم","x":"الربيع المرادي كان ضعيف الفهم حتى قال له الشافعي: «يا ربيع، لو قدرت أن أطعمك العلم لأطعمتك إياه»، ثم فُتح عليه (ص103 و104)."},{"h":"للعلم","x":"الشافعي كان منشغلًا بالشعر فصرفته كلمة عجوز إلى الفقه، والذهبي حُبّب إليه الحديث بكلمة من البرزالي (ص104)."},{"h":"دعاء المعتكف","x":"أحد جهابذة الحديث في زمننا كان ضعيف الحفظ فاعتكف يدعو حتى صار لا يسمع حديثًا إلا انتقش في ذهنه (ص104)."}]},{"t":"فتح الدعاء والقرآن","pg":105,"key":"ومن غرائب الفتوح أن يفتح الله عليك في ذكره، وحمده، ودعائه!","p":["رأيت النووي وهو ابن عشر سنين، والصبيان يُكرهونه على اللعب معهم وهو يهرب منهم ويبكي لإكراههم ويقرأ القرآن في تلك الحال، فوقع في نفسي محبّته"],"items":[{"h":"صورتان","x":"الأولى فتح الخشوع والإخبات، كحال النبي ﷺ في دعائه يوم بدر، والثانية فتح المحامد التي لم يكن العبد يعلمها (ص105 و106)."},{"h":"فتيان المساجد","x":"انظر إلى فتيان عكفوا على حفظ القرآن بعد العصر والمغرب «لتعلم أنّ الله يصطفي لكتابه من أراد من عباده» (ص107)."}]},{"t":"فتوح الغرائب ومواهب الفتاح","pg":107,"key":"ومن الفتوحات الربانيّة أن يعطيك الله العطاء بكيفية، لا يعطى ذاك العطاء في العادة بتلك الكيفيّة!","p":["ومن ذلك أن ترجو عطاء، فيعطيك الله ما هو أعظم منه!"],"items":[{"h":"زمن وجيز","x":"الزمخشري كتب تفسيره في نحو ثلاث سنين، وابن القيم ألّف زاد المعاد في سفر (ص108 و109)."},{"h":"موسى عليه السلام","x":"ذهب يطلب جذوة نار فنال النبوة: «أراد الاصطلاء فنال الاصطفاء!» (ص110)."},{"h":"مواهب الفتاح","x":"«فإذا أحبّ الله باطن عبده، ظهرت عليه مواهب الفتّاح» ومن ذلك المحبة في قلوب الناس، كأويس القرني والربيع بن خثيم (ص111)."},{"h":"السعي على الأيتام","x":"رجل اهتم بالأيتام والأرامل فتيسرت أموره، «ولعلّ ذلك من الفتوح التي وهبه إيّاها الله لسعيه على أولئك الأيتام والأرامل!» (ص112)."}]}],"quiz":[{"q":"ما «قانون البشرى» الذي يذكره المؤلف؟","o":["أن الله يرسل قبل الرحمة بشائر تهيئ لها","أن البشارة لا تأتي إلا في المنام","أن الرحمة تأتي فجأة بلا مقدمات أو بشائر","أن البشرى خاصة بالأنبياء دون غيرهم"],"why":"فهو سبحانه لا يرسل الرحمة وحدها، بل يرسل قبلها البشائر التي تهيئك لتقبّل تلك الرحمات، وتلقّي تلك البركات.","pg":102},{"q":"ما الذي يضمن بقاء النعم وزيادتها كما في الكتاب؟","o":["شكر الله عليها","كتمانها عن الناس","إنفاقها كلها فورًا","الحذر من الحاسدين"],"why":"إن الشكر لا يضمن بقاء الرحمة فحسب، بل ويتكفّل بزيادتها!","pg":102},{"q":"بمن مثّل المؤلف للفتح «للعلم»، أي أن يُصرف المرء إليه بعد انشغاله بغيره؟","o":["الشافعي حين ردّته عجوز إلى الفقه","الربيع حين فُتح عليه بعد ضعف فهمه","ابن تيمية حين استغلقت عليه آية","الزمخشري حين كتب تفسيره بمكة"],"why":"أما الفتح للعلم، فقد كان إمام الدنيا محمد بن إدريس الشافعي منشغلًا بالشعر، ففتح الله عليه بكلمة قالتها له عجوز","pg":104},{"q":"ما المثال الذي ساقه المؤلف لمن رجا عطاءً فأُعطي أعظم منه؟","o":["موسى ذهب يطلب النار فنال النبوة","النووي هرب من اللعب إلى القرآن","الربيع طلب الفهم فأُعطي الحفظ والفقه","الذهبي طلب الخط فأُعطي الفقه"],"why":"أراد الاصطلاء فنال الاصطفاء!","pg":110},{"q":"رجل ضعيف الحفظ لا يكاد يحفظ حديثًا؛ ماذا صنع نظيره الذي ذكره المؤلف؟","o":["اعتكف يدعو الله أن يفتح عليه","ترك الحديث إلى علم آخر أيسر منه","اكتفى بكتابة الأحاديث دون حفظها","سافر إلى بلد آخر يبحث عن شيخ"],"why":"فاعتكف في أحد المساجد لا يدعو الله إلا بأن يفتح عليه في العلم، قال: فما قضيت اعتكافي ذلك ودعواتي تلك حتى صرت لا أسمع بحديث إلا وينتقش في ذهني!","pg":104}],"scene":{"t":"صغير يحب القرآن","x":"ابنك في العاشرة يحب حفظ القرآن، وأقرانه يسخرون منه ويلحّون عليه أن يلعب معهم. ماذا تفعل؟","opts":["تشجعه وتحكي له قصة النووي الصغير وما فتح الله عليه","تطلب منه أن يلعب معهم حتى لا يُنبذ","تؤجل حفظه حتى يكبر ويصبح أقدر"],"why":"رأيت النووي وهو ابن عشر سنين، والصبيان يُكرهونه على اللعب معهم وهو يهرب منهم ويبكي لإكراههم ويقرأ القرآن في تلك الحال، فوقع في نفسي محبّته","pg":107}},{"k":"c8","t":"القدير","q":"كيف يدعو العبد ربًّا لا يعجزه شيء؟","essence":"ما يريده كائن، فادعه بيقين","kw":["القدرة","اليقين","المعاندة"],"sections":[{"t":"فعّال لما يريد","pg":115,"key":"فكل ما يريده إرادة كونيّة سيكون لأنّه يفعل كل ما يريد، لا رادّ لمشيئته، ولا معقّب لحكمه.","p":["فيطرق باب هذه الإرادة بالدعاء والابتهال والتضرّع، ثم ينتقل من عبادة الدعاء إلى عبادة انتظار الفرج، أما سحابة القنوط فيستحيل أن تمرّ بسماء فكره، لأنّ ربّه قدير."],"items":[{"h":"ماء لا ينسكب","x":"«ولكن من عادة الإنسان ألا يُبصر القريب، ولا يُبهَر بالمعتاد»، فالأرض غالبيتها ماء لا ينسكب (ص116)."},{"h":"أبيات أبي نواس","x":"«تأمّل في نبات الأرض وانظر، إلى آثار ما صنع المليك» (ص116)."}]},{"t":"هو عليّ هيّن","pg":117,"key":"إن شفاء المريض، أو معافاة المبتلى، أو كشف كربة المحزون.. من أهون ما قد تمسّه قدرة الله سبحانه","p":["فلذلك لا بد من استحضارك عندما تمدّ يديك داعيًا في حاجتك أنّك تدعو القدير على أن يخلق المعجزات، وأن يحقق المستحيلات، وأن يوجد المدهشات!"],"items":[{"h":"تقديم «عليّ»","x":"«وتقديم الجار والمجرور «عليّ» على متعلّقهما «هيّن».. يشي بأن ذلك من العسير والصعب بل والمستحيل على غير الله تعالى.. ولكنّه «عليه» هيّن!» (مريم 21) (ص117)."},{"h":"الصرخة","x":"غافر 57: «فبما أنه قد خلق الأكبر والأعظم، فكيف تتردد في أن تسأله الأصغر والأهون؟» (ص118)."}]},{"t":"اطرق بيد موسى","pg":119,"key":"وألّا تطرق باب قدرته بيد مترددة، أو بيد مختبرة، اطرق بابه بيد كيد موسى عندما ضرب بها البحر","p":["إن الله عزيز، لا يعطي أولئك الذي لا يثقون بقدرته، وبأنّه الله!"],"items":[{"h":"انشقاق القمر","x":"طلب كفار قريش أن يشق القمر فانشق نصفين (القمر 1) (ص120)."},{"h":"نسفًا","x":"طه 105 إلى 107: «لم يقل: يهدمها أو يطيح بها.. فالهدم والإطاحة لا تضمن التفتت التام» (ص122)."}]},{"t":"ما وراء المستحيل","pg":123,"key":"من غريب قدرة الله تعالى أنها لا تتوقف عند الأشياء التي نظنّها مستحيلة، أو صعبة، بل قدرته في الصنع تشبه إبداعه في الخلق!","p":["فانشقاق البحر ليس مستحيل الوقوع فقط، بل مستحيل التخيّل!"],"items":[{"h":"رفع الجبل","x":"الأعراف 171: رفع الجبل فوق بني إسرائيل أمر لا يدور في العقول خيالًا (ص123)."},{"h":"قدرة غير معهودة","x":"«الذي قدرته ليست غير قدرة البشر، بل غير ما يعرفه البشر عن القدرة!» (ص123)."}]},{"t":"إذا هم عصوه","pg":124,"key":"ومن عجائب قدرته أنّه سبحانه لا يمنعه عن أن ينزل العقوبة على العصاة إلا أنه حليم ودود!","p":["إنّه القدير الذي لا ينبغي أن يُستغضب؛ لأنّه يقدر على أن يسكتك بكن فيكون!"],"items":[{"h":"ابن الجوزي","x":"«أسرع المعاصي عقوبة ما خلا عن لذة تنسي النهي، فتكون تلك الخطيئة كالمعاندة والمبارزة» (صيد الخاطر) (ص124)."},{"h":"أبو الدرداء","x":"بكى لما فُتحت قبرص وقال: «ما أهون العباد على الله إذا هم عصوه!» (ص125)."}]}],"quiz":[{"q":"ما الذي استخرجه المؤلف من تقديم «عليّ» على «هيّن» في قوله تعالى «هو عليّ هيّن»؟","o":["أنه عسير على غيره هيّن عليه وحده","أن الأمر هيّن على كل أحد من الخلق","أن خلق الولد أعظم من خلق السماوات","أن زكريا لم يستبعد الولد أصلًا"],"why":"وتقديم الجار والمجرور «عليّ» على متعلّقهما «هيّن».. يشي بأن ذلك من العسير والصعب بل والمستحيل على غير الله تعالى.. ولكنّه «عليه» هيّن!","pg":117},{"q":"ما حجة المؤلف من آية غافر 57 لمن يستبعد شفاء مريضه؟","o":["من خلق الأكبر لا يُستبعد عليه الأصغر","أن الشفاء لا يكون إلا بالدواء وحده دائمًا","أن خلق الناس أكبر من خلق السماوات","أن المرض قدر لا يرفعه الدعاء مهما كثر"],"why":"فبما أنه قد خلق الأكبر والأعظم، فكيف تتردد في أن تسأله الأصغر والأهون؟","pg":118},{"q":"ينهى المؤلف عن طرق باب القدرة «بيد مختبرة»؛ فما المقصود؟","o":["الدعاء تجريبًا وترددًا لا يقينًا","الدعاء بعد الأخذ بالأسباب المادية كلها","رفع اليدين دون نطق بالدعاء أصلًا","تكرار الدعاء نفسه مرات عدة في المجلس"],"why":"يكون رفع اليدين إليه بالدعاء على وجه التشكك والتردد، وبطريقة المختبر لا المستيقن؟","pg":119},{"q":"لماذا وصف المؤلف انشقاق البحر بأنه «مستحيل التخيّل»؟","o":["لأنه فوق طاقة البشر في التخيّل أصلًا","لأنه وقع ليلًا فلم يره أحد من الناس","لأن المؤرخين لم يثبتوا وقوعه حتى اليوم","لأنه حدث بريح قوية معروفة السبب"],"why":"فانشقاق البحر ليس مستحيل الوقوع فقط، بل مستحيل التخيّل!","pg":123},{"q":"«كم أنت هيّن على الله إذا حاولت أن تستغضبه!» أي حال يتناولها هذا القول؟","o":["المعصية على وجه المعاندة والمبارزة","الخطأ الذي يقع سهوًا ونسيانًا","الذنب الذي يتبعه ندم وتوبة صادقة","التقصير في النوافل والمستحبات اليومية"],"why":"أسرع المعاصي عقوبة ما خلا عن لذة تنسي النهي، فتكون تلك الخطيئة كالمعاندة والمبارزة","pg":124}],"scene":{"t":"حالة صعبة","x":"أخبرك الطبيب أن حالة والدك صعبة جدًا، وصرت تدعو وفي نفسك: لا أظن أن شيئًا سيتغير. ماذا تفعل؟","opts":["تدعو بيقين أن شفاءه هيّن على القدير مع الأخذ بالأسباب","تترك الدعاء لأن الطبيب أعلم بالحالة","تدعو مرة على سبيل التجربة لترى ما يحدث"],"why":"فلذلك لا بد من استحضارك عندما تمدّ يديك داعيًا في حاجتك أنّك تدعو القدير على أن يخلق المعجزات، وأن يحقق المستحيلات، وأن يوجد المدهشات!","pg":118}},{"k":"c9","t":"الولي","q":"ما معنى ولاية الله، وكيف ينالها العبد؟","essence":"يتولى عباده عونًا ونصرة، والقرآن طريقها","kw":["الولاية","الاستعانة","القرآن"],"sections":[{"t":"معنيا الولي","pg":129,"key":"فالولاية من العبد الطاعة والعبادة، والولاية من الربّ الإعانة والإفادة!","p":["فالله هو الولي الذي يتولاه عبده بعبادته وطاعته، والتقرب إليه بما أمكن من أنواع التقربات، ويتولى عباده عمومًا بتدبيره، ونفوذ القدر فيهم، ويتولى عباده المؤمنين خصوصًا، بإخراجهم من الظلمات إلى النور، وتربيتهم بلطفه، وإعانتهم في جميع أمورهم"],"items":[{"h":"الولاية العامة","x":"«فالولاية العامّة تعمّ جميع الخلق، فهو المدبّر لمعاشهم، والمعين لهم على ضوائق الحياة واحتياجاتها..» (ص129)."},{"h":"الولاية الخاصة","x":"«والولاية الخاصّة تخصّ عباده المؤمنين، فهو وليّهم بنصره، وبهدايته، وبفضله وألطافه.» (ص129)."},{"h":"مصدر النقل","x":"النص الحرفي أعلاه للسعدي في تيسير الكريم الرحمن (ص129 و130)."}]},{"t":"هباءة","pg":130,"key":"الإنسان هباءة في كون فسيح، إذا لم يأته مدد الإعانة والتوفيق والتيسير من الله ضاع..","p":["فلا يستطيع العبد أن يكون عبدًا إذا لم يُعنه الله.. ولا يكون عبدًا إذا لم يطلب العون من الله.."],"items":[{"h":"إياك نستعين","x":"قرن الله بين العبادة والاستعانة في الفاتحة 5 (ص130)."},{"h":"لا بديل","x":"«ليس هناك ولي يعوّض عن حاجة الروح إلى ولاية الله تعالى» (الشورى 9) (ص131)."}]},{"t":"بدء المعركة","pg":131,"key":"إنه وليّهم، ولا يترك الوليُّ وليّه، بل يحوطه بحبه وعنايته، ويصنعه على عينه، ويصطنعه لنفسه!","p":[],"items":[{"h":"الحديث","x":"«إن الله قال: من عادى لي وليًا فقد آذنته بالحرب» رواه البخاري (ص131)."},{"h":"ينشر رحمته","x":"الشورى 28، والبقرة 257: «يضيء لك الولي بنوره تلك الظلمات فتتبدد» (ص133)."}]},{"t":"وجيف قلب والدرع الواقي","pg":133,"key":"وينهاك عن أمر، ثم يعينك بأن يجعل تطلّبه عسيرًا عليك، ويوصد الأبواب المفضية إليه، ويعينك بأن يغمرك بكآبة ووجيف قلب إذا ما اقتربت منه، ويعينك بأن يحيطك بالندم ساعة فعله حتى لا تكرر فعله","p":["يأمرك الله بالأمر، ثم يعينك بالقوّة على امتثاله، ويعينك بأن يجعل روحك تهفو لعمله"],"items":[{"h":"الدرع الواقي","x":"«ومن مظاهر ولايته سبحانه أن يخلق خلقه ضعفاء، ثم يجعل من ضمن ما يخلقه فيهم قوى ووسائل تعينهم على هذه الحياة من جانب جلب المنافع وجانب دفع المضار!» (ص134)."},{"h":"يتيم ولكن","x":"الإمام أحمد اليتيم أعانه الله بأم صابرة، وحافظة قوية، وفهم، وصمود في المحنة (ص135)."}]},{"t":"أخبره بتفاصيلك ويتولى الصالحين","pg":136,"key":"وإجابة الدعوات من أشكال ولايته لعباده، وحبّه، وإعانته!","p":["والصالحون الذين يتولاهم هم أهل هذا القرآن الكريم.. وكلما اقترب العبد من القرآن علمًا وعملًا واعتقادًا، فقد اقترب من الولاية نصرة وتأييدًا وإعانة."],"items":[{"h":"السجدة الطويلة","x":"أوصى أحد الدعاة مكروبًا: «أريدك الليلة أن تقف بين يديه سبحانه، ثم تسجد له سجدة طويلة تشرح فيها لله ما شرحت لي» فانفرجت همومه (ص136 و137)."},{"h":"حفظ القرآن","x":"«وليس لحفظ القرآن عمر محدد، ولا لحفظة القرآن تخصص معيّن! التخصص الوحيد لهم هو الإسلام» (ص139)."}]}],"quiz":[{"q":"أي مما يلي يدخل في الولاية «الخاصة» كما يقسمها المؤلف؟","o":["نصر المؤمنين وهدايتهم إلى النور","تدبير معاش جميع الخلق وأرزاقهم","إعانة كل الكائنات على ضرورات الحياة","نفوذ القدر في جميع العباد عمومًا"],"why":"والولاية الخاصّة تخصّ عباده المؤمنين، فهو وليّهم بنصره، وبهدايته، وبفضله وألطافه.","pg":129},{"q":"في ضوء «إياك نعبد وإياك نستعين»، متى يكون العبد عبدًا بحسب المؤلف؟","o":["إذا طلب العون من الله وأحس بحاجته","إذا استغنى بقدراته عن طلب العون","إذا أكثر من الأعمال دون سؤال ولا دعاء","إذا طلب العون من الناس أولًا"],"why":"فلا يستطيع العبد أن يكون عبدًا إذا لم يُعنه الله.. ولا يكون عبدًا إذا لم يطلب العون من الله..","pg":130},{"q":"كيف يعين الولي عبده على ترك ما نهاه عنه كما في الكتاب؟","o":["يعسّر طلبه ويغمره بالكآبة إذا اقترب منه","يرفع عنه الشهوة فلا يميل إليها أبدًا","يعاقبه في الحال قبل أن يقع فيها","يتركه لنفسه حتى يتعلم من خطئه وحده"],"why":"وينهاك عن أمر، ثم يعينك بأن يجعل تطلّبه عسيرًا عليك، ويوصد الأبواب المفضية إليه، ويعينك بأن يغمرك بكآبة ووجيف قلب إذا ما اقتربت منه","pg":133},{"q":"من «الصالحون» الذين يتولاهم الله في آية الأعراف 196 بحسب المؤلف؟","o":["أهل القرآن علمًا وعملًا واعتقادًا","الزهاد الذين اعتزلوا الناس كليًا","أصحاب الكرامات الظاهرة للناس","الفقهاء دون غيرهم من عامة المسلمين"],"why":"والصالحون الذين يتولاهم هم أهل هذا القرآن الكريم.. وكلما اقترب العبد من القرآن علمًا وعملًا واعتقادًا، فقد اقترب من الولاية نصرة وتأييدًا وإعانة.","pg":138},{"q":"رجل أثقلته الكروب فاتصل بأحد الدعاة؛ بم أوصاه؟","o":["أن يسجد سجدة طويلة يشرح فيها حاله","أن يكتب همومه في ورقة ثم يتلفها فورًا","أن يسافر بعيدًا ليغيّر أجواءه","أن يقرأ سورة بعينها سبع مرات"],"why":"أريدك الليلة أن تقف بين يديه سبحانه، ثم تسجد له سجدة طويلة تشرح فيها لله ما شرحت لي، وتفصّل في دعائك ما فصّلت لي، ولا ترفع رأسك وفي نفسك شيء لم تقله له.","pg":136}],"scene":{"t":"كبرت على الحفظ","x":"قال لك زميل في الأربعين: فات أوان حفظي للقرآن، ولست طالب علم. ماذا تقول له؟","opts":["تذكّره أنه لا عمر لحفظ القرآن ولا تخصص له سوى الإسلام","توافقه وتقترح عليه الاكتفاء بالاستماع","تقول له إن الحفظ خاص بالصغار"],"why":"وليس لحفظ القرآن عمر محدد، ولا لحفظة القرآن تخصص معيّن! التخصص الوحيد لهم هو الإسلام","pg":139}},{"k":"c10","t":"القوي","q":"كيف يستمد الضعيف قوته من القوي؟","essence":"القوة لله، وكل متكبر إلى زوال","kw":["القوة","الضعف","المتكبرون"],"sections":[{"t":"الضعف صفة لازمة","pg":143,"key":"سبحان من جعل الضعف صفة لازمة للإنسان، ونعتًا مصاحبًا لحياته القصيرة!","p":["وجَعَل سبحانه القوّة له، والكبرياء له، والعظمة له، حتى يلجأ إليه الضعفاء فينصُرَهم، ويلوذ به المنكسرون فيجبُرَهم، ويتوجّه إليه المكروبون فيرفعَ ما بهم من كَرب.","فهو القويّ العزيز، لا قوّة تقوم مع قوّته، كلُّ الأقوياء ضعفاء على أعتاب جبروته، وكل المتكبرين مساكين في إيوان ملكه."],"items":[]},{"t":"ولا قوة إلا بالله","pg":144,"key":"من ظلال اسم الله القوي أنّه هو الذي يهب القوّة لمن استمدّها منه سبحانه","p":["فمن قوّته سبحانه تُستمد القوى، وبفضلها تذوب الكثير من الأوجاع والآلام والصعوبات، لأنّ القويّ هو وحده من يجعلك قويًّا تتجاوز ضعف جسدك، وهشاشة روحك، وانكسار نفسك.."],"items":[{"h":"قصة الكرسي","x":"رجل كان يسعى بين الصفا والمروة على كرسي، فلزم ذكر «لا حول ولا قوة إلا بالله» متأملًا، فاعتمر ثلاث مرات يكاد يركض (ص144 و145)."},{"h":"الذكر استيهاب","x":"«وأنّ هذا الذكر هو بمثابة استجداء واستيهاب لهذه القوّة!» (ص144)."},{"h":"السماء بلا عمد","x":"الذاريات 47: «والأيد القوّة» (ص146)."}]},{"t":"إني سقيم","pg":146,"key":"وليعلم الإنسان شيئًا عن قوّة خالقه لينظر إلى ضعفه وقلّة حيلته في حالة المرض!","p":["لقد سلّط الله على الإنسان في هذه الدنيا كمًّا هائلًا من الأمراض، ليعلن الإنسان عجزه في هذه الحياة، وكمال احتياجه للقوي سبحانه، فلا يغتر بقوة ما"],"items":[{"h":"أمثلة","x":"الحمى والشلل والتهاب العصب وقرحة المعدة والسرطان والحزام الناري (ص147 و148)."},{"h":"جرعة","x":"يتأمل ألم مريض في المستشفى ويستغرب قول الملحدين: «ما قيمة إله لا يستطيع أن يمنع الآلام أن تغزو جسده!» (ص150)."}]},{"t":"يقهر المتكبرين","pg":152,"key":"ويخص القويّ المتكبرين بأعجب النهايات، وأغرب الأمراض، وأنكى الأوجاع، ليعلم الضعفاء أنّ الله وحده القويّ، وكل ما عداه ضعيف هزيل متهالك!","p":["ليس هناك ظالم إلا وبيده فناؤه، ولا جبّار إلا وفي قدرته أن يقصمه، ولا متكبر إلا بكلمة يجعله لا شيء."],"items":[{"h":"فرعون","x":"قال «أنا ربكم الأعلى» (النازعات 24) فمات غرقًا (ص152)."},{"h":"يسحقون أنفسهم","x":"«ومن مظاهر قوّته وعزّته أنّه يجعل بعض أعدائه يقومون هم بسحق أنفسهم» كهتلر (ص153)."},{"h":"بين الخيام","x":"سليمان بن عبد الملك في مرض موته: «يا من لا يزول ملكه، ارحم من زال ملكه..» (ص154)."},{"h":"الجبال","x":"«كلّما كبر في نفس الإنسان شيء، وبلغ من الكِبَر المنتهى، بدّد سبحانه ذلك الشيء بكلمة منه!» (ص151)."}]},{"t":"عندما يُظلم الضعيف","pg":156,"key":"لا قويّ إلا والله أقوى منه! ولا عزيز إلا والله أعزّ منه..","p":["وإذا زعزعتك المخاوف فتوكّل على القويّ.. وإذا هدّ قواك الظلم فاستجر بالقويّ.."],"items":[{"h":"مات!","x":"صاحب للمؤلف ضربه ظالم أمام الناس: «صليت ركعتين كلهما دموع، واستنصرت بالله القوي العزيز!» (ص156)."},{"h":"شاهد الزور","x":"أسرة في تبوك دعت على شاهد زور فاعترف الجاني في الصباح بعد موت الشاهد (ص157 و158)."}]}],"quiz":[{"q":"ما الحكمة التي يذكرها المؤلف من جعل الضعف للإنسان والقوة لله؟","o":["أن يلجأ إليه الضعفاء فينصرهم ويجبرهم","أن ييأس الإنسان من تغيير حاله وواقعه","أن يستغني الضعيف عن الأسباب كلها بالدعاء","أن يتساوى الناس في القوة والضعف"],"why":"وجَعَل سبحانه القوّة له، والكبرياء له، والعظمة له، حتى يلجأ إليه الضعفاء فينصُرَهم، ويلوذ به المنكسرون فيجبُرَهم، ويتوجّه إليه المكروبون فيرفعَ ما بهم من كَرب.","pg":143},{"q":"كيف وصف المؤلف ذكر «لا حول ولا قوة إلا بالله» في قصة صاحب الكرسي؟","o":["استجداء واستيهاب من الله","ذكر يقال عند المصائب وحدها","عبارة عن العجز واليأس من التغيير","ذكر خاص بمناسك الحج والعمرة"],"why":"وأنّ هذا الذكر هو بمثابة استجداء واستيهاب لهذه القوّة!","pg":144},{"q":"ما الغاية من كثرة الأمراض التي سُلطت على الإنسان كما يرى المؤلف؟","o":["أن يعلن عجزه وحاجته فلا يغتر بقوة","أن يُعاقب على كل ذنب يعمله في الحال","أن يترك العمل ويلزم بيته حتى يُشفى","أن يتعلم الطب فيستغني به عن غيره"],"why":"لقد سلّط الله على الإنسان في هذه الدنيا كمًّا هائلًا من الأمراض، ليعلن الإنسان عجزه في هذه الحياة، وكمال احتياجه للقوي سبحانه، فلا يغتر بقوة ما","pg":146},{"q":"ما الذي يجمع نهايات فرعون وهتلر وغيرهما في هذا الفصل؟","o":["ادّعوا القوة فانتهوا أضعف نهاية","أنهم جميعًا ماتوا غرقًا في البحر","أنهم تابوا قبيل موتهم بقليل","أنهم هُزموا في حروب كبرى فقط"],"why":"ليس هناك ظالم إلا وبيده فناؤه، ولا جبّار إلا وفي قدرته أن يقصمه، ولا متكبر إلا بكلمة يجعله لا شيء.","pg":161},{"q":"صاحب المؤلف ضربه ظالم أمام الناس؛ ماذا فعل بعدها؟","o":["صلى ركعتين باكيًا واستنصر بالقوي","جمع أصحابه ليرد عليه بمثل فعله","شكاه إلى كبار أهل الحي ليؤدبوه","سكت ونسي ما جرى له في يومه ذاك"],"why":"صليت ركعتين كلهما دموع، واستنصرت بالله القوي العزيز!","pg":156}],"scene":{"t":"ظلم في العمل","x":"تعرضت لظلم من مسؤول متسلط في عملك، ولا تملك قوة لرده. ماذا تفعل؟","opts":["تتوكل على القوي وتستجير به مع سلوك الطرق المشروعة","تنتقم منه بطرق خفية مماثلة","تيأس وتظن أن الظالم لا يُحاسب"],"why":"وإذا زعزعتك المخاوف فتوكّل على القويّ.. وإذا هدّ قواك الظلم فاستجر بالقويّ..","pg":152}},{"k":"c11","t":"البديع","q":"كيف يدل الإبداع في الكون على الخالق؟","essence":"كل شيء مبدع على غير مثال سابق","kw":["الإبداع","الأصوات والألوان","الشكر"],"sections":[{"t":"معنى البديع","pg":165,"key":"الإبداع يحمل معانيَ أخرى غير الإيجاد والخلق.. الإبداع هو أن يخلق الشيء على غير مثال سابق..","p":["فالكون صفحة لا تحتاج إلى تعمّق حتى تدلّنا على الخالق البديع سبحانه.."],"items":[{"h":"أسماء متقاربة","x":"«لله ﷻ أسماء تشترك في معان وتفترق في أخرى! من بينها: الخالق والبارئ والمصوّر والبديع..» (ص165)."},{"h":"كل شيء","x":"«إنّ لكل شيء في الكون، وأنا أعني حرفيًا (كل شيء) إبداع يخصّه!» (ص165)."}]},{"t":"معجزة الصوت","pg":166,"key":"فمما أبدعه الله تعالى في كونه وأوجده على غير مثال سابق عالم الأصوات المكتظ بالحياة..","p":["فيخلق في حنجرة كل إنسان نبرة خاصة، وخامة خاصة، ولمسة شخصيّة"],"items":[{"h":"لو تشابهت الأصوات","x":"«دعنا نتخيّل أن البشر كلّهم يملكون خامة صوتيّة واحدة» لاختلطت الحياة (ص167)."},{"h":"نباح الديك","x":"«وديك يصيح، علم الله أن صباحاتنا ستكون بشعة لو أن صوته نباح لا صياح!» (ص170)."},{"h":"أفي الله شك","x":"إبراهيم 10: «هل ينبغي أن يخالج النفس شك في هذا الرب الذي لم يغفل عن هذه التفاصيل الغاية في الدقة» (ص170)."}]},{"t":"العين واللون","pg":171,"key":"ومما أبدعه البديع سبحانه أن يرى الإنسان الصور والمشاهد!","p":["ثم تتعجب لرب لم يردك أن تزاول الأشياء الجادة فقط، بل أرادك أن ترى الأشياء جميلة ببهجة ذات ألق فريد."],"items":[{"h":"درس العصابة","x":"عصب عيني طالب وطلب منه إيصال قلم إلى زميل فتاه، ثم نفّذه بلا عصابة في ثوان (ص171)."},{"h":"الأكمه في ينبع","x":"رجل وُلد أعمى لا يعرف شيئًا عن الألوان ولا جمال الطبيعة (ص172)."},{"h":"عمى الألوان","x":"زميل يرى الأخضر بنيًا، ونظارة تعيد للمصابين ألوانهم فينبهرون (ص173 و174)."}]},{"t":"كأس وشذى وعنبر ولؤلؤ","pg":176,"key":"البديع سبحانه ينتج عن هذا الامتزاج ألذ شراب، وأجمل لون، وأعظم معجزة، إنّها معجزة اللبن الخالص السائغ!!","p":["إن الله تعالى يخلق مثل هذه الغرائب حتى يتيح للبشرية أن تقول: «سبحان الله»!"],"items":[{"h":"اللبن","x":"«من بين فرث ودم لبنًا خالصًا سائغًا للشاربين» (النحل 66) (ص176)."},{"h":"المسك","x":"ينتج عن غدة في بطن نوع من الغزلان (ص177)."},{"h":"العنبر","x":"«فهنا رائحة تنتج من لا رائحة! وشيء يصدر من ضدّه، ومخلوق يُخلق من عكسه!» (ص179)."},{"h":"اللؤلؤ","x":"ذرة دخيلة تحيطها المحارة بسجن كلسي فيصير لؤلؤة (ص180)."}]},{"t":"وفي أنفسكم والشمس","pg":182,"key":"إنّ الله من العظمة بحيث يستطيع أن ينقل مسرح المعجزات إلى داخلك، ويجعلك أنت المعجزة الكونيّة المذهلة","p":["هنا تدرك معنى البديع، وأنّه أتقن وأبدع كل شيء خلقه.. وأنّ مُكثك طوال حياتك ساجدًا له، لن يؤدّيَ شكر نعمة واحدة من نعمه التي أبدعها، ووهبها لك.. دون أن تسألَه إيّاها، بل دون أن تدرك مدى حاجتك لها."],"items":[{"h":"الشمس","x":"القصص 71: بلا شمس يظلم الكون ويتجمد ولا ينبت زرع (ص183 إلى 185)."},{"h":"الأكسجين","x":"«فإن كانت الحياة بلا شمس مستحيلة البقاء، فإنها بلا أكسجين مستحيلة الوجود أصلًا!» (ص185)."}]}],"quiz":[{"q":"بم يختص معنى «الإبداع» عن مطلق الخلق في الكتاب؟","o":["أن يُخلق الشيء على غير مثال سابق","أن يُخلق الشيء في وقت قصير جدًا","أن يُخلق الشيء من مادة سبقته","أن يُخلق الشيء عظيم الحجم بالغ القوة"],"why":"الإبداع يحمل معانيَ أخرى غير الإيجاد والخلق.. الإبداع هو أن يخلق الشيء على غير مثال سابق..","pg":165},{"q":"ما الذي استدل به المؤلف من آية النحل 66 «من بين فرث ودم لبنًا خالصًا»؟","o":["إخراج شراب لذيذ من مزيج منفّر","أن اللبن يتكون من الدم وحده دون غيره","أن الفيزياء تفسر كل امتزاج في الطبيعة","أن الحيوان أحق بالتأمل من الإنسان"],"why":"البديع سبحانه ينتج عن هذا الامتزاج ألذ شراب، وأجمل لون، وأعظم معجزة، إنّها معجزة اللبن الخالص السائغ!!","pg":176},{"q":"ما وجه الإبداع في العنبر الذي أبرزه المؤلف؟","o":["رائحة زكية تنتج من مادة لا رائحة لها","يُستخرج من زهرة نادرة تنبت في قاع البحر","يتكون في غدة في بطن نوع من الغزلان","أنه أغلى العطور ثمنًا في العالم"],"why":"فهنا رائحة تنتج من لا رائحة! وشيء يصدر من ضدّه، ومخلوق يُخلق من عكسه!","pg":179},{"q":"لماذا يرى المؤلف أن معجزة وجودك ليست بأقل من شق البحر؟","o":["لأن الله نقل مسرح المعجزات داخلك","لأن المعجزات انتهت بموت الأنبياء","لأن شق البحر لم يره إلا قليل","لأن جسدك أعظم من البحر حجمًا وأثرًا"],"why":"إنّ الله من العظمة بحيث يستطيع أن ينقل مسرح المعجزات إلى داخلك، ويجعلك أنت المعجزة الكونيّة المذهلة","pg":182},{"q":"كيف أشعر المؤلف طلابه بنعمة البصر دون كلام كثير؟","o":["عصب عيني طالب وكلّفه بإيصال قلم","عرض عليهم مقطعًا مرئيًا عن المكفوفين","طلب منهم كتابة مقال عن العين","أطفأ أنوار الفصل ساعة كاملة"],"why":"أقمت طالبًا وعصبت على عينيه، وأمرته بأمر سهل، كأنْ يأخذ قلمًا من على الطاولة ثم يعطيه الطالب الفلاني..","pg":171}],"scene":{"t":"درس البصر","x":"تريد أن يشعر طلابك بنعمة البصر التي ألفوها حتى لم يعودوا يشعرون بها. ماذا تفعل؟","opts":["تعصب عيني طالب وتكلفه بمهمة يسيرة ثم تكررها بلا عصابة","تلقي عليهم محاضرة طويلة عن تشريح العين","تطلب منهم حفظ أجزاء العين للاختبار"],"why":"ثم هداني الله لأسلوب سهل لا يحتاج إلى كثير من الكلام، وقد أدّى مفعوله المؤثر في قلوب الطلاب","pg":171}}],"highlights":[{"x":"إن الرحمٰن إذا نشر رحمته في مكان مظلم أضاء، وفي كهف ضيّق بات فسيحًا، وفي قلب ميّت نبض بالحياة.","pg":14},{"x":"فسبحان من رحمته فيما نكره قد تكون أعظم وأظهر من رحمته فيما نحب!","pg":22},{"x":"الصباح مسرح من مسارح الجمال","pg":34},{"x":"إن الوهّاب لم يخلق بابًا دون هباته وعطاياه، فقط قل: يا الله، ثم استبشر خيرًا..","pg":43},{"x":"إنّ أعتى الملاحدة يتحوّل في الليل إلى نصف مؤمن!","pg":57},{"x":"فلا تظنّ بالحكيم تخلّف حكمته، ولا بالرحيم قصور رحمته.","pg":74},{"x":"ما أجمل الحلم بعد العلم، لأن علم الإنسان ببواطن الناس يستغضبه ويُحنقه، أما علم الله سبحانه فلا يَنقُص من حلمه ورحمته شيئًا.","pg":93},{"x":"أراد الاصطلاء فنال الاصطفاء!","pg":110},{"x":"كم أنت هيّن على الله إذا حاولت أن تستغضبه!","pg":125},{"x":"لا قويّ إلا والله أقوى منه! ولا عزيز إلا والله أعزّ منه..","pg":157},{"x":"لكل شيء صوت.. ولكل صوت معنى.. ولكل معنى عمق يجعل الحياة حياة","pg":171}],"concepts":[{"term":"الحكمة","def":"الحكمة هي وضع الأمر في موضعه، والحكيم هو الذي يفعل ذلك!","pg":65},{"term":"الوهّاب","def":"وصيغة فعّال تعني المبالغة، فليس سبحانه واهبًا بل وهّابًا: كثيرًا ما يهب ويعطي ويجود، لذلك سمّى نفسه بالوهّاب..","pg":39},{"term":"الاستيهاب بالهبات السابقة","def":"أن تذكر في دعائك بعض ما سبق ووهبك إيّاه، فتكون هبته السالفة أمرًا تستجدي به هبة جديدة!","pg":40},{"term":"غرابة الدعاء","def":"لم يكن الأنبياء في كثير من دعواتهم يدعون بالقريب وإنما بالغريب!","pg":45},{"term":"الحق المبين","def":"فهو الحق الذي ليس بعده إلا الباطل، ظاهر ظهورًا جليًّا، لا يماري في وجوده، وفي عليائه، وفي جلاله إلا أعمى البصيرة.","pg":53},{"term":"الإحاطة","def":"يعلم ما كان، وما يكون، وما لم يكن لو كان كيف يكون!","pg":96},{"term":"قانون البشرى","def":"فهو سبحانه لا يرسل الرحمة وحدها، بل يرسل قبلها البشائر التي تهيئك لتقبّل تلك الرحمات، وتلقّي تلك البركات.","pg":102},{"term":"الولاية","def":"فالولاية من العبد الطاعة والعبادة، والولاية من الربّ الإعانة والإفادة!","pg":129},{"term":"الولاية العامة","def":"فالولاية العامّة تعمّ جميع الخلق، فهو المدبّر لمعاشهم، والمعين لهم على ضوائق الحياة واحتياجاتها..","pg":129},{"term":"الولاية الخاصة","def":"والولاية الخاصّة تخصّ عباده المؤمنين، فهو وليّهم بنصره، وبهدايته، وبفضله وألطافه.","pg":129},{"term":"الإبداع","def":"الإبداع هو أن يخلق الشيء على غير مثال سابق..","pg":165}],"links":[{"topic":"الدعاء وآدابه","pg":45},{"topic":"الشكر","pg":102},{"topic":"الإلحاد والرد عليه","pg":55},{"topic":"الابتلاء والمرض","pg":146},{"topic":"الإخلاص","pg":88},{"topic":"حفظ القرآن","pg":139},{"topic":"الظلم ونصرة المظلوم","pg":156},{"topic":"التأمل في الخلق","pg":166},{"topic":"التوبة","pg":43}]};
